import types

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    def __init__(self, x, y, srid=None, **kwargs):
        Point.__init__(self, x, y)
        self._srid = srid
        for field, value in kwargs.items():
            if field in fields:
                setattr(self, field, value)

    def __repr__(self):
        srid_str = f", srid={self._srid}" if self._srid else ""
        field_str = ", ".join(f"{field}={getattr(self, field)}" for field in fields if hasattr(self, field))
        return f"{name}({self.x}, {self.y}{srid_str}, {field_str})"

    attributes = {
        '__init__': __init__,
        '__repr__': __repr__,
        '__module__': __name__
    }

    for field in fields:
        attributes[field] = None

    new_type = types.new_class(name, (Point,), {}, lambda ns: ns.update(attributes))
    return new_type

