def difference(d1, d2, level=-1):
    import copy

    def dict_diff(d1, d2, current_level):
        diff = {}
        for k, v1 in d1.items():
            if k not in d2:
                diff[k] = v1
            else:
                v2 = d2[k]
                if isinstance(v1, dict) and isinstance(v2, dict):
                    if level == -1 or current_level < level:
                        sub_diff = dict_diff(v1, v2, current_level + 1)
                        if sub_diff:
                            diff[k] = sub_diff
                elif v1 != v2:
                    diff[k] = v1
        return diff

    return copy.deepcopy(dict_diff(d1, d2, 0))

