def _validate_labels(labels: Dict[Union[str, int, bool], Union[str, List[str]]]):
    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_\- ]+$')
    errors = []

    for key, value in labels.items():
        key_str = str(key)
        if not isinstance(key, (str, int, bool)):
            errors.append({key_str: 'expected string, integer, or boolean as key'})
        elif isinstance(key, str) and not key_regex.match(key):
            errors.append({key_str: f"Label key '{key}' does not match the regex '^[a-zA-Z0-9_]+$'"})

        if isinstance(value, str) and not value_regex.match(value):
            errors.append({key_str: f"Label value '{value}' does not match the regex '^[a-zA-Z0-9_\\- ]+$'"})
        elif isinstance(value, Iterable) and not all(isinstance(item, str) and value_regex.match(item) for item in value):
            errors.append({key_str: f"Label value '{value}' contains invalid elements"})

    if errors:
        raise ValidationError(errors)

