def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    for obs_field, resp_field in zip(observer_schema, response):
        if isinstance(obs_field, dict) and isinstance(resp_field, dict):
            if len(last_applied_manifest) <= observer_schema.index(obs_field):
                last_applied_manifest.append({})
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[observer_schema.index(obs_field)],
                obs_field,
                resp_field
            )
        elif isinstance(obs_field, list) and isinstance(resp_field, list):
            if len(last_applied_manifest) <= observer_schema.index(obs_field):
                last_applied_manifest.append([])
            if len(last_applied_manifest[observer_schema.index(obs_field)]) < len(resp_field):
                last_applied_manifest[observer_schema.index(obs_field)].extend([{}] * (len(resp_field) - len(last_applied_manifest[observer_schema.index(obs_field)])))
            for i, (sub_obs, sub_resp) in enumerate(zip(obs_field, resp_field)):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[observer_schema.index(obs_field)][i],
                    sub_obs,
                    sub_resp
                )
        else:
            if len(last_applied_manifest) <= observer_schema.index(obs_field):
                last_applied_manifest.append(None)
            if last_applied_manifest[observer_schema.index(obs_field)] is None:
                last_applied_manifest[observer_schema.index(obs_field)] = resp_field

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for field, schema in observer_schema.items():
        if field in response:
            if isinstance(schema, dict) and isinstance(response[field], dict):
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema, response[field]
                )
            else:
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = response[field]
        else:
            raise KeyError(f"The observed field '{field}' is not present in the Kubernetes response")

