from typing import AnyStr, Any, Dict, Union, Sequence, Tuple

class SQLParams:
    in_style = 'named'  # or 'ordinal'

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if SQLParams.in_style == 'named':
        if not isinstance(params, dict):
            raise ValueError("Params must be a dict for named parameter style.")
        out_params = {f":{key}": value for key, value in params.items()}
        for key in out_params:
            sql = sql.replace(f":{key.split(':')[1]}", key)
        return sql, out_params
    elif SQLParams.in_style == 'ordinal':
        if not isinstance(params, Sequence):
            raise ValueError("Params must be a sequence for ordinal parameter style.")
        out_params = [value for value in params]
        sql = sql % tuple(f":{i}" for i in range(len(out_params)))
        return sql, out_params
    else:
        raise ValueError("Unsupported parameter style.")

from typing import Any, AnyStr, Dict, Iterable, List, Sequence, Tuple, Union

class SQLParams:
    in_style = 'named'  # or 'ordinal'

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    out_params = []
    if SQLParams.in_style == 'named':
        out_sql = sql
        for params in many_params:
            out_param = {}
            for key, value in params.items():
                out_sql = out_sql.replace(f':{key}', f'%({key})s')
                out_param[key] = value
            out_params.append(out_param)
    elif SQLParams.in_style == 'ordinal':
        out_sql = sql
        for params in many_params:
            out_param = []
            for i, value in enumerate(params):
                out_sql = out_sql.replace(f'%{i + 1}', f'%s')
                out_param.append(value)
            out_params.append(out_param)
    return out_sql, out_params

