def check_digests_present_and_used(self, manifest_files, digests_used):
    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as file:
            manifest_data = file.read()
            # Assuming manifest_data is a JSON string, parse it
            import json
            manifest = json.loads(manifest_data)
            for entry in manifest:
                if 'digest' in entry and entry['digest'] in digests_used:
                    if manifest[entry]['used'] is not True:
                        return False
                elif 'digest' in entry and entry['digest'] not in digests_used:
                    return False
