def absorb(self, args: List['Expression']) -> List['Expression']:
    def apply_absorption(expr: 'Expression') -> 'Expression':
        if expr.operator == "&":
            if expr.operands[0] == expr.operands[1].operands[0] and expr.operands[1].operator == "|":
                return expr.operands[0]
            if expr.operands[0] == expr.operands[1].operands[1] and expr.operands[1].operator == "|":
