            if expr.operands[0].operands[0] == expr.operands[1] and expr.operands[0].operator == "~":
                return Expression("&", [expr.operands[0].operands[0], expr.operands[1].operands[1]])
            if expr.operands[0].operands[1] == expr.operands[1] and expr.operands[0].operator == "~":
                return Expression("&", [expr.operands[0].operands[1], expr.operands[1].operands[0]])
        if expr.operator == "|":
            if expr.operands[0] == expr.operands[1].operands[0] and expr.operands[1].operator == "&":
                return expr.operands[0]
            if expr.operands[0] == expr.operands[1].operands[1] and expr.operands[1].operator == "&":
                return expr.operands[0]
            if expr.operands[0].operands[0] == expr.operands[1] and expr.operands[0].operator == "~":
