def deep_merge_nodes(nodes):
    merged = {}

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged:
            merged[key] = (key_node, value_node)
        else:
            _, existing_value_node = merged[key]
            if isinstance(existing_value_node, MappingNode) and isinstance(value_node, MappingNode):
                existing_value_node.value.extend(value_node.value)
            else:
                merged[key] = (key_node, value_node)

    # Remove duplicates in MappingNode values
    for key in merged:
        key_node, value_node = merged[key]
        if isinstance(value_node, MappingNode):
            seen = set()
            unique_items = []
            for item_key_node, item_value_node in value_node.value:
                item_key = item_key_node.value
                if item_key not in seen:
                    seen.add(item_key)
                    unique_items.append((item_key_node, item_value_node))
            value_node.value = unique_items

    return list(merged.values())

