from ruamel.yaml.nodes import ScalarNode, MappingNode

def deep_merge_nodes(nodes):
    merged = {}

    for key_node, value_node in nodes:
        key = key_node.value

        if key not in merged:
            merged[key] = (key_node, value_node)
        else:
            _, existing_value_node = merged[key]

            if isinstance(value_node, MappingNode) and isinstance(existing_value_node, MappingNode):
                new_value = []
                existing_value_dict = {child[0].value: child for child in existing_value_node.value}

                for child_key_node, child_value_node in value_node.value:
                    child_key = child_key_node.value
                    if child_key in existing_value_dict:
                        _, existing_child_value_node = existing_value_dict[child_key]
                        if isinstance(child_value_node, MappingNode) and isinstance(existing_child_value_node, MappingNode):
                            new_value.append((child_key_node, deep_merge_nodes([(child_key_node, existing_child_value_node), (child_key_node, child_value_node)])[0][1]))
                        else:
                            new_value.append((child_key_node, child_value_node))
                    else:
                        new_value.append((child_key_node, child_value_node))

                for child_key_node, child_value_node in existing_value_node.value:
                    if child_key_node.value not in [c[0].value for c in value_node.value]:
                        new_value.append((child_key_node, child_value_node))

                merged[key] = (key_node, MappingNode(tag=existing_value_node.tag, value=new_value))
            else:
                merged[key] = (key_node, value_node)

    return list(merged.values())

