class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if not (0 <= ticks < 86400000000000):
            raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")
        midnight = datetime.combine(datetime.today(), datetime.min.time()).replace(tzinfo=tz)
        delta = timedelta(microseconds=ticks // 1000)
        return cls(midnight + delta)

