import numpy as np

class Histogram:
    def __init__(self):
        self.data = []
        self._scale = None

    def scale(self, other=None, recompute=False):
        if other is None:
            if self._scale is None or recompute:
                self._scale = np.sum(self.data)
            return self._scale
        else:
            if self._scale is None:
                raise ValueError("Scale has not been computed yet.")
            if self._scale == 0:
                raise ValueError("Cannot rescale a histogram with scale equal to zero.")
            factor = other / self._scale
            self.data = [x * factor for x in self.data]
            self._scale = other
            return self._scale

class Graph:
    def __init__(self, scale=None, coordinates=None, errors=None):
        self._scale = scale
        self._coordinates = coordinates or []
        self._errors = errors or []

    def scale(self, other=None):
        if other is None:
            if self._scale is None or self._scale == 0:
                raise ValueError("Graph has unknown or zero scale")
            return self._scale
        else:
            if self._scale is None or self._scale == 0:
                raise ValueError("Graph has unknown or zero scale")
            scale_factor = other / self._scale
            if self._coordinates:
                self._coordinates[-1] *= scale_factor
            if self._errors:
                self._errors[-1] *= scale_factor
            self._scale = other
            return self._scale

