def hist_to_graph(hist: Histogram, make_value: Callable[[Union[float, Tuple]], Tuple[float, ...]] = None, 
                  get_coordinate: str = "left", field_names: Tuple[str, ...] = ("x", "y"), scale: Union[bool, str] = None) -> Graph:
    if make_value is None:
        make_value = lambda bin_: (bin_,)

    points = []
    for bin_left, bin_content in hist.bins:
        if get_coordinate == "left":
            x = bin_left
        elif get_coordinate == "right":
            x = bin_left + (hist.bins[hist.bins.index((bin_left, bin_content)) + 1][0] - bin_left) if hist.bins.index((bin_left, bin_content)) < len(hist.bins) - 1 else bin_left + 1
        elif get_coordinate == "middle":
            x = bin_left + 0.5 * (hist.bins[hist.bins.index((bin_left, bin_content)) + 1][0] - bin_left) if hist.bins.index((bin_left, bin_content)) < len(hist.bins) - 1 else bin_left + 0.5
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        y_values = make_value(bin_content)
        points.append((x,) + y_values)

    graph_scale = hist.scale if scale is True else scale

    return Graph(points, field_names, graph_scale)

from zope.interface import Interface, providedBy, Invalid
import inspect

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set([name for name, value in iface.namesAndDescriptions() if inspect.isfunction(value)])
    required_attributes = set([name for name, value in iface.namesAndDescriptions() if not inspect.isfunction(value)])

    candidate_methods = set(dir(candidate)) if vtype is None else set(dir(vtype))

    missing_methods = required_methods - candidate_methods
    if missing_methods:
        errors.extend([f"Missing method: {method}" for method in missing_methods])

    missing_attributes = required_attributes - candidate_methods
    if missing_attributes:
        errors.extend([f"Missing attribute: {attr}" for attr in missing_attributes])

    for name, value in iface.namesAndDescriptions():
        if name in candidate_methods and inspect.isfunction(value):
            candidate_method = getattr(candidate, name)
            if inspect.signature(candidate_method) != inspect.signature(value):
                errors.append(f"Method {name} has incorrect signature: {inspect.signature(candidate_method)} vs {inspect.signature(value)}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid('\n'.join(errors))

    return True

from zope.interface import verify, Invalid

def verifyObject(iface, candidate, tentative=False):
    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"{candidate} does not claim to provide {iface}")

    for name in iface:
        if name.isDeclaration():
            continue

        if not hasattr(candidate, name):
            errors.append(f"{candidate} does not have {name}")

        if callable(getattr(iface, name)):
            candidate_method = getattr(candidate, name, None)
            if candidate_method is None or not callable(candidate_method):
                errors.append(f"{candidate} does not have a callable {name}")

            iface_method = getattr(iface, name)
            iface_method_signature = iface_method.__signature__
            candidate_method_signature = candidate_method.__signature__

            if iface_method_signature is not None and candidate_method_signature is not None:
                bound_signature = iface_method_signature.bind_partial(*candidate_method_signature.parameters.values())
                try:
                    bound_signature.apply_defaults()
                except TypeError as e:
                    errors.append(f"{candidate} has an incorrect signature for {name}: {e}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

