import re
from typing import Tuple, Set, Callable

def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set[str], str]:
    code_block_pattern = re.compile(r'`.*?`|".*?"|\'.*?\'')
    tag_pattern = re.compile(r'(?<!\w)(#\w+)(?!\w)')

    # Find all code blocks and replace them with placeholders
    code_blocks = code_block_pattern.findall(text)
    placeholders = {f"__CODE_BLOCK_{i}__": block for i, block in enumerate(code_blocks)}
    for placeholder, block in placeholders.items():
        text = text.replace(block, placeholder)

    # Find all tags in the text
    tags = set(tag_pattern.findall(text))

    # Optionally replace tags
    if replacer:
        def replace_tag(match):
            tag = match.group(0)
            return replacer(tag)
        text = tag_pattern.sub(replace_tag, text)

    # Restore code blocks
    for placeholder, block in placeholders.items():
        text = text.replace(placeholder, block)

    return tags, text

