import json
from xml.etree import ElementTree
from typing import Dict, Any

def parse_diaspora_webfinger(document: str) -> Dict[str, Any]:
    try:
        # Try to parse as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ElementTree.fromstring(document)
            # Extracting information from XRD
            data = {}
            for element in root.iter():
                if element.tag.endswith('}') and len(element.tag.split('}')) > 1:
                    tag = element.tag.split('}')[-1]
                else:
                    tag = element.tag
                data[tag] = element.text or {}
            return data
        except ElementTree.ParseError:
            # If both parsing attempts fail, return an empty dictionary
            return {}

