import yaml

class IRValidatorException(Exception):
    pass

class Validator:
    @classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        required_fields = {'name', 'version', 'description'}

        if yaml_file is None:
            raise IRValidatorException("No YAML file provided")

        try:
            with open(yaml_file, 'r') as file:
                data = yaml.safe_load(file)
        except FileNotFoundError:
            raise IRValidatorException(f"File {yaml_file} not found")
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML file: {e}")

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a dictionary")

        missing_fields = required_fields - data.keys()
        if missing_fields:
            raise IRValidatorException(f"Missing fields in YAML file: {missing_fields}")

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    import os
    import yaml

    if 'include' in parser_dict:
        include_paths = parser_dict.pop('include')
        for path in include_paths:
            if os.path.exists(path):
                with open(path, 'r') as file:
                    included_dict = yaml.safe_load(file)
                    parser_dict.update(included_dict)
    return parser_dict

