            key, value = arg.split('=', 1)
            if re.match(r'^custom_', key):
                nested_args[key] = value
            else:
                nested_args[key] = value

    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is None:
        extra_vars = []
    for extra_var in extra_vars:
        key, value = extra_var.split('=')
        vars_dict[key] = value
    return vars_dict

import subprocess
import shlex

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    cmd = ['ansible-playbook', playbook_path]

    if verbose:
        cmd.extend(['-' + 'v' * verbose])

    if extra_vars:
        extra_vars_str = ' '.join([f'{k}={v}' for k, v in extra_vars.items()])
        cmd.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        for arg, value in ansible_args.items():
            if value is None:
                cmd.append(shlex.quote(arg))
            else:
                cmd.extend([shlex.quote(arg), shlex.quote(str(value))])

    subprocess.run(cmd, check=True)

